#!/usr/bin/env python3
from pathlib import Path
import base64, hashlib
ROOT=Path(__file__).resolve().parents[3]
MAGICA=ROOT/'magica'
def replace(path,old,new,count=1):
 p=MAGICA/path; s=p.read_text(encoding='utf-8'); actual=s.count(old)
 if actual!=count: raise SystemExit(f"{path}: expected {count} occurrences of {old!r}, got {actual}")
 p.write_text(s.replace(old,new),encoding='utf-8',newline='\n')
