replace('template/campaign/gacha_lineup/CampaignGachaLineUp.html','>选择对象一览<','>可选对象一览<',1)
replace('template/gacha/GachaTop.html','>选择对象一览<','>可选对象一览<',2)
replace('template/gacha/GachaTop.html','>获得记录<','>获得履历<',1)
replace('template/gacha/GachaTop.html','>抽卡概率一览<','>卡池一览<',1)
