res=base64.b64decode(''); rp=MAGICA/'template/gacha/GachaResult.html'; rp.parent.mkdir(parents=True,exist_ok=True)
if rp.exists() and rp.read_bytes()!=res: raise SystemExit('template/gacha/GachaResult.html unexpectedly exists with different bytes')
