expected={'js/campaign/box_gacha/CampaignBoxGachaTop.js': '17664ae667c33e937db760ed660cec9ae792cca274f4f8bf200d0d28e534cbd3', 'js/gacha/GachaResult.js': 'cfe8edaddf77d7c034f3a224341281b3776bc05206f1ba2ee35c020bfce3b7ea', 'template/campaign/box_gacha/CampaignBoxGachaTop.html': 'c37a11523c71d0b68aea25cf17c5f8be4235e0a55e45887bc3687cc6c53c309f', 'template/gacha/GachaAnimation.html': '9fc840ae38f02376c0edc826bdd9ecd2bb2afc55624b3b8d786bf71bb629dbf1', 'template/gacha/GachaResult.html': 'b51f670ef688d3a68d459724c3b4763612cb9d8bc19fff6fc9c99ebb05287500', 'template/gacha/SelectableGachaCharaSelect.html': '4dd51752abe51a1a8a4e688727251809e2b2f04c24e23cfb7396681b3f6dde01', 'template/gacha/SelectableGachaPieceSelect.html': '323ec7c4416dea19cb9b602974e5495687205e44adae161785824235ccee5df3', 'template/campaign/gacha_lineup/CampaignGachaLineUp.html': '2d9b5630f7918da8caade53e69f8ba320b27f9322a621ec555297badd03f2b49', 'template/gacha/GachaTop.html': '601cf07133e81910ec1ea7c1b26933064681df22c8697dcd34f6c754add29b3c', 'template/gacha/GachaProbabilityPop.html': '478a75b132a8b899765fd2903f4b20b0e356e1cf41f2f43d20c2982177e07012'}
for rel,digest in expected.items():
 p=MAGICA/rel
 if not p.exists(): raise SystemExit(f'missing expected output: {rel}')
 got=hashlib.sha256(p.read_bytes()).hexdigest()
 if got!=digest: raise SystemExit(f'output hash mismatch {rel}: {got} != {digest}')
print('gacha CN overlay applied and verified:',len(expected),'files')
